cd /home/nick/work/andesim
for f in tests/plugin/test_plugin_oracle_exit_drain.sh tests/fixtures/test_gemm_source.sh tests/fixtures/test_gemm_markerless_twin.sh tests/hsim/test_hsim_kanata.sh; do
